INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('neuroform-ai', 'NeuroForm AI', 'Le générateur de formulaires intelligents qui crée, teste et optimise vos formulaires en 30 secondes.', 'NeuroForm IA génère des formulaires complets à partir d''une simple description textuelle, puis les optimise en continu grâce au machine learning. Les taux de conversion sont mesurés en temps réel et l''IA propose des variantes à tester (A/B testing automatique).
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('pixelpeek', 'PixelPeek API', 'API de captures d''écran pixel-perfect de n''importe quelle page web, en 200 ms.', 'PixelPeek transforme n''importe quelle URL en capture d''écran haute définition via une simple requête REST. Rendu Chrome headless, émulation mobile, injection de cookies, blocage des pop-ups et attente de sélecteur avant capture.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('clipforge', 'ClipForge', 'Gestionnaire de presse-papiers pour développeurs : historique infini, snippets et recherche instantanée.', 'ClipForge garde en mémoire chaque élément copié (texte, code, couleurs, images) avec un historique illimité et une recherche instantanée par mot-clé ou par application source. Les snippets récurrents deviennent des modèles réutilisables avec placeholders.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('termvault', 'TermVault', 'Coffre-fort de mots de passe en ligne de commande, chiffré localement, compatible teams.', 'TermVault ramène la sécurité au terminal : vos secrets sont chiffrés localement (AES-256-GCM, clé maîtresse dérivée via Argon2) puis synchronisés de bout en bout. Aucun serveur tiers n''accède à vos données en clair.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('reposentinel', 'RepoSentinel', 'Scanner CLI qui audite vos dépôts GitHub : secrets exposés, dépendances vulnérables, mauvaises pratiques.', 'RepoSentinel analyse vos dépôts en local avant chaque push et bloque les fuites de secrets (clés API, tokens, certificats) grâce à plus de 140 motifs de détection. Il vérifie aussi les dépendances vulnérables (CVE) et signale les fichiers trop permissifs.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('hydrotrack', 'HydroTrack', 'Suivi d''hydratation gamifié : rappels intelligents, badges et widgets d''écran d''accueil.', 'HydroTrack vous aide à boire régulièrement sans y penser : objectifs personnalisés selon votre poids et votre activité, rappels adaptatifs (pas pendant vos réunions !), badges de série et animations célébrant chaque palier.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('fokusflow', 'FokusFlow', 'Minuteur Pomodoro avec son ambiant génératif et statistiques de concentration profonde.', 'FokusFlow va plus loin que le simple Pomodoro : il génère des paysages sonores adaptatifs ( pluie, café, brown noise) dont l''intensité suit vos cycles de concentration, et mesure votre « temps de focus profond » réel grâce à l''analyse des interruptions.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('dev-independant', 'Le Dev Indépendant', 'E-book de 230 pages : lancez une activité de développeur solo rentable en 90 jours.', 'La méthode complète pour passer de salarié à développeur indépendant sans y perdre : positionnement, tarification au valeur, prospection par contenu, gestion administrative (statuts, URSSAF, TVA) et automatisation de la production.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('prompt-alchemy', 'Prompt Alchemy', 'Mini-guide gratuit : les 12 principes pour écrire des prompts qui produisent des résultats exploitables.', 'Un e-book court et dense (42 pages) qui décortique l''anatomie d''un prompt efficace : rôle, contexte, contraintes, format de sortie et exemples few-shot. Chaque principe est illustré d''un avant/après mesurable sur GPT-4, Claude et Gemini.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('megapack-prompts', 'MegaPack 500 Prompts', '500 prompts testés et catégorisés pour marketing, code, design et productivité — prêts à copier.', 'Le MegaPack réunit 500 prompts professionnels testés sur des projets réels, classés en 8 catégories (SEO, copywriting, développement, design, analyse de données, e-mailing, support client, automatisation). Chaque fiche indique le modèle recommandé, les variables à personnaliser et le résultat attendu.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('flowbridge-n8n', 'FlowBridge — Pack n8n', '40 workflows n8n prêts à l''emploi : CRM, facturation, veille, publication sociale et support.', 'FlowBridge est une collection open-source de 40 workflows n8n documentés et versionnés, prêts à importer en un clic. Chaque workflow est accompagné d''un guide d''installation, des variables d''environnement attendues et d''une vidéo de démonstration.
INSERT INTO products (id, title, short_description, description, category, action_type, badges, price, action_url, apk_url, pwa_url, command, video_url, image_url, clicks, created_at, updated_at) VALUES ('zenpost', 'ZenPost', 'Planificateur social qui écrit, programme et recycle vos contenus sur 6 réseaux.', 'ZenPost centralise votre production de contenu : rédaction assistée par IA calée sur votre voix de marque, calendrier visuel, publication programmée sur X, LinkedIn, Instagram, TikTok, Bluesky et Threads, et recyclage intelligent de vos meilleurs posts.
